def write_seg(seg, ids_expected):
    for cid, ptext, basis_body, conf, trig in seg:
        rec = {"case_id": cid,
               "prediction_text": ptext,
               "basis": "tradition: liuyao\n" + basis_body,
               "confidence": conf,
               "trigger": trig}
        (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    got = []
    for cid in ids_expected:
        rec = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
        assert rec["case_id"] == cid, cid
        got.append(cid)
    assert got == ids_expected, (got, ids_expected)
    print("SEGMENT OK", len(got), got[0], got[-1])

if __name__ == "__main__":
    write_seg(B13, BATCHES["B13"])
    print("B13 done")

